typedef float rational_t;
typedef int axis_id_t;

const rational_t AXIS_MAX = 1.0f;
const rational_t AXIS_MID = 0.0f;
const rational_t AXIS_MIN = -1.0f;
const float BOOLEAN_AXIS_FUDGE_FACTOR = 0.75f;

enum control_t
{
  CT_BOOLEAN,
  CT_RATIONAL,
};

class stringx;
class input_device
{
public:
  virtual stringx get_name() const = 0;
  virtual stringx get_name(int axis) const = 0;
  virtual int get_id() const = 0;
  virtual int get_axis_count() const = 0;
  virtual axis_id_t get_axis_id(int axis) const = 0;
  virtual rational_t get_axis_state(axis_id_t axis, int control_axis) const = 0;
  virtual rational_t get_axis_old_state(axis_id_t axis, int control_axis) const = 0;
  virtual rational_t get_axis_delta(axis_id_t axis, int control_axis) const = 0;
};

class input_mgr
{
public:
  rational_t get_control_delta_helper(input_device *devptr, axis_id_t axis, int control_axis, control_t ctype) const;
};

#define assert(expr) ((void)0)

rational_t input_mgr::get_control_delta_helper(input_device *devptr, axis_id_t axis, int control_axis, control_t ctype ) const
{ // just a helper function for get_control_delta function so we don't write duplicate code
  assert(devptr);

  rational_t retval;

  if ( ctype == CT_BOOLEAN )
  {
    rational_t v0 = devptr->get_axis_old_state( axis, control_axis );
    if ( v0 < AXIS_MIN*BOOLEAN_AXIS_FUDGE_FACTOR )
      v0 = AXIS_MIN;
    else if ( v0 > AXIS_MAX*BOOLEAN_AXIS_FUDGE_FACTOR )
      v0 = AXIS_MAX;
    else
      v0 = AXIS_MID;

    rational_t v1 = devptr->get_axis_state( axis, control_axis );
    if ( v1 < AXIS_MIN*BOOLEAN_AXIS_FUDGE_FACTOR )
      v1 = AXIS_MIN;
    else if ( v1 > AXIS_MAX*BOOLEAN_AXIS_FUDGE_FACTOR )
      v1 = AXIS_MAX;
    else
      v1 = AXIS_MID;

    retval = v1 - v0;
    if ( retval < 0 )
      retval = AXIS_MIN;
    else if ( retval > 0 )
      retval = AXIS_MAX;
  }
  else
  {
    retval = devptr->get_axis_delta( axis, control_axis );
  }

  return retval;
}
